apiVersion: apps/v1
kind: Deployment
metadata: {name: web}
spec:
  replicas: 3
  selector: {matchLabels: {app: web}}
  template:
    {metadata: {labels: {app: web}}, spec: {containers: [{name: nginx, image: nginx}]}}

http: {paths: [{path: /api, pathType: Prefix,
      backend: {service: {name: api,
        port: {number: 80}}}}]}
